// Keep only KEV entries added inside the lookback window that match your tech stack
const config = $('Configuration').first().json;
const catalog = $input.first().json;
const vulns = catalog.vulnerabilities || [];

const stack = String(config.techStack || '')
  .split(',')
  .map(term => term.trim().toLowerCase())
  .filter(Boolean);

const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - Number(config.lookbackDays || 7));

const matches = vulns.filter(v => {
  if (new Date(v.dateAdded) < cutoff) return false;
  if (stack.length === 0) return true; // empty tech stack = watch everything
  const haystack = `${v.vendorProject} ${v.product}`.toLowerCase();
  return stack.some(term => haystack.includes(term));
});

return matches.map(v => ({
  json: {
    cveID: v.cveID,
    vendor: v.vendorProject,
    product: v.product,
    name: v.vulnerabilityName,
    description: v.shortDescription,
    requiredAction: v.requiredAction,
    dateAdded: v.dateAdded,
    dueDate: v.dueDate,
    knownRansomwareUse: v.knownRansomwareCampaignUse,
    cwes: v.cwes || [],
    references: v.notes,
    nvdUrl: `https://nvd.nist.gov/vuln/detail/${v.cveID}`,
  },
}));

// Merge EPSS data back onto each KEV entry and assign a priority
const config = $('Configuration').first().json;
const threshold = Number(config.epssHighThreshold ?? 0.1);
const kevItems = $('Remove Previously Alerted CVEs').all();
const rank = { Critical: 0, High: 1, Medium: 2 };

const results = $input.all().map((item, i) => {
  const kev = kevItems[i].json;
  const row = (item.json.data || [])[0];
  const epss = row ? Number(row.epss) : null;
  const epssPercentile = row ? Number(row.percentile) : null;
  const ransomware = kev.knownRansomwareUse === 'Known';

  let priority = 'Medium';
  if (ransomware || (epss !== null && epss >= 0.5)) priority = 'Critical';
  else if (epss !== null && epss >= threshold) priority = 'High';

  const daysUntilDue = Math.ceil((new Date(kev.dueDate) - new Date()) / 86400000) + 0; // + 0 normalizes -0

  return { json: { ...kev, epss, epssPercentile, priority, daysUntilDue } };
});

results.sort((a, b) =>
  rank[a.json.priority] - rank[b.json.priority] || (b.json.epss ?? 0) - (a.json.epss ?? 0)
);

return results;

